/**
 * The fidelity gate: every golden case is replayed through the real engine and compared with what
 * Neovim produced for the same keys (expectations generated by tools/golden/generate.ts).
 */
import { readFileSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { createEngine } from '../../packages/engine/src/engine.js';
import { runGolden, type Case } from './runner.js';

const CASES_DIR = join(dirname(fileURLToPath(import.meta.url)), 'cases');

for (const file of readdirSync(CASES_DIR).filter((name) => name.endsWith('.json'))) {
  const cases = JSON.parse(readFileSync(join(CASES_DIR, file), 'utf8')) as Case[];
  describe(`golden: ${file}`, () => {
    for (const result of runGolden(createEngine(), cases)) {
      it(result.name, () => {
        expect(result.differences, JSON.stringify({ actual: result.actual, expected: result.expected })).toEqual([]);
      });
    }
  });
}
